pub const BLOCK_TX_BLOB: usize = 56;
pub const BLOCK_STATE_ROOT: usize = 64;
pub const BLOCK_PROOF: usize = 72;
pub const BLOCK_SIZE: usize = 80;

/// A view of a ZAP-encoded Block. Reading a field costs a bounds check.
#[derive(Clone, Copy, Debug)]
pub struct Block<'a> {
    o: zap::Object<'a>,
}

impl<'a> Block<'a> {
    /// Take `data` as a Block message. Fails only on the wire-level
    /// checks — magic, version, declared size.
    pub fn wrap(data: &'a [u8]) -> Result<Self, zap::Error> {
        Ok(Block {
            o: zap::Message::parse(data)?.root(),
        })
    }

    /// A view of an object already located in a message — a nested
    /// field, or one element of a list.
    pub fn new(o: zap::Object<'a>) -> Self {
        Block { o }
    }

    /// The object this view reads.
    pub fn object(&self) -> zap::Object<'a> {
        self.o
    }

    /// The 32 inline bytes at `BLOCK_PARENT`; zeros if the span runs off the buffer.
    pub fn parent(&self) -> &'a [u8; 32] {
        self.o
            .bytes_fixed(BLOCK_PARENT, 32)
            .try_into()
            .unwrap_or(&[0u8; 32])
    }

    pub fn height(&self) -> u64 {
        self.o.u64(BLOCK_HEIGHT)
    }

    pub fn time(&self) -> i64 {
        self.o.i64(BLOCK_TIME)
    }

    pub fn tx_lens(&self) -> zap::List<'a> {
        self.o.list_stride(BLOCK_TX_LENS, 4)
    }

    pub fn tx_blob(&self) -> &'a [u8] {
        self.o.bytes(BLOCK_TX_BLOB)
    }

    pub fn state_root(&self) -> &'a [u8] {
        self.o.bytes(BLOCK_STATE_ROOT)
    }

    pub fn proof(&self) -> &'a [u8] {
        self.o.bytes(BLOCK_PROOF)
    }
}

/// The field values [`new_block`] writes.
#[derive(Clone, Copy, Debug)]
pub struct BlockInput<'a> {
    pub parent: &'a [u8; 32],
    pub height: u64,
    pub time: i64,
    pub tx_lens: &'a [u32],
    pub tx_blob: &'a [u8],
    pub state_root: &'a [u8],
    pub proof: &'a [u8],
}

impl<'a> Default for BlockInput<'a> {
    fn default() -> Self {
        BlockInput {
            parent: &[0u8; 32],
            height: 0,
            time: 0,
            tx_lens: &[],
            tx_blob: &[],
            state_root: &[],
            proof: &[],
        }
    }
}

/// Write a Block into `b` and answer where its object landed.
///
/// What a field points AT is written first, in field order, and the
/// fixed section last: a pointer always leads backward, to bytes
/// already placed.
pub fn put_block(b: &mut zap::Builder, input: &BlockInput<'_>) -> usize {
    let mut list_tx_lens = b.start_list();
    for elem in input.tx_lens {
        list_tx_lens.add_u32(b, *elem);
    }
    let at_tx_lens = list_tx_lens.finish_offset();
    let mut ob = b.start_object(BLOCK_SIZE);
    ob.set_bytes_fixed(b, BLOCK_PARENT, input.parent);
    ob.set_u64(b, BLOCK_HEIGHT, input.height);
    ob.set_i64(b, BLOCK_TIME, input.time);
    ob.set_list(b, BLOCK_TX_LENS, at_tx_lens, input.tx_lens.len());
    ob.set_bytes(b, BLOCK_TX_BLOB, input.tx_blob);
    ob.set_bytes(b, BLOCK_STATE_ROOT, input.state_root);
    ob.set_bytes(b, BLOCK_PROOF, input.proof);
    ob.finish(b)
}

/// Write a Block message and answer its bytes.
pub fn new_block(input: &BlockInput<'_>) -> Vec<u8> {
    let mut b = zap::Builder::new_v2(256);
    let at = put_block(&mut b, input);
    b.set_root(at);
    b.finish()
}

